import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    static Set<String> toplam(String satr) {
        Set<String> toplam = new HashSet<>();
        Scanner s = new Scanner(satr);
        while (s.hasNext()) {
            toplam.add(s.next());
        }
        return toplam;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Set<String> adapter = toplam(in.nextLine());
        Set<String> port = toplam(in.nextLine());
        Set<String> adapterDuplex = toplam(in.nextLine());
        Set<String> portDuplex = toplam(in.nextLine());
        String tanlangan = "no link";
        for (String tezlik : new String[] {"10", "100", "1000"}) {
            if (adapter.contains(tezlik) && port.contains(tezlik)) {
                tanlangan = tezlik;
                break;
            }
        }
        if (tanlangan.equals("no link")) {
            System.out.println(tanlangan);
        } else {
            String rejim = adapterDuplex.contains("full") && portDuplex.contains("full") ? "full" : "half";
            System.out.println(tanlangan + " " + rejim);
        }
    }
}

