#include <iostream>
#include <set>
#include <sstream>
#include <string>
using namespace std;

set<string> toplam(const string& satr) {
    set<string> toplam;
    string soz;
    stringstream oqim(satr);
    while (oqim >> soz) {
        toplam.insert(soz);
    }
    return toplam;
}

int main() {
    string l1, l2, l3, l4;
    getline(cin, l1);
    getline(cin, l2);
    getline(cin, l3);
    getline(cin, l4);
    set<string> adapter = toplam(l1);
    set<string> port = toplam(l2);
    set<string> adapterDuplex = toplam(l3);
    set<string> portDuplex = toplam(l4);
    string nomlar[] = {"10", "100", "1000"};
    string tanlangan = "no link";
    for (int i = 0; i < 3; i++) {
        if (adapter.count(nomlar[i]) && port.count(nomlar[i])) {
            tanlangan = nomlar[i];
            break;
        }
    }
    if (tanlangan == "no link") {
        cout << tanlangan << endl;
    } else {
        string rejim = (adapterDuplex.count("full") && portDuplex.count("full")) ? "full" : "half";
        cout << tanlangan << " " << rejim << endl;
    }
    return 0;
}

